struct Node { int val; Node *left, *right; };
void inorder(Node* r) {
    if (!r) return;
    inorder(r->left);
    cout << r->val << " ";
    inorder(r->right);
}

java.code:
class Node {
    int val; Node left, right;
    Node(int v) { val = v; }
}
static void inorder(Node r) {
    if (r == null) return;
    inorder(r.left);
    System.out.print(r.val + " ");
    inorder(r.right);
}

python.code:
class Node:
    def __init__(self, val, left=None, right=None):
        self.val, self.left, self.right = val, left, right

def inorder(r):
    if not r: return
    inorder(r.left)
    print(r.val, end=" ")
    inorder(r.right)

